PRAGMA foreign_keys = ON;

-- Handbook remediation: historical reference pages and each core page intro now have distinct business meaning.
UPDATE pages
SET title =
    CASE (CAST(substr(page_id, -3) AS INTEGER) % 15)
      WHEN 0 THEN 'junior-class between-class cadence review' WHEN 1 THEN 'weekend long-class lunch record' WHEN 2 THEN 'game-record head-down duration observation'
      WHEN 3 THEN 'screen-review offscreen record' WHEN 4 THEN 'classroom lighting change notes' WHEN 5 THEN 'short-walk execution review'
      WHEN 6 THEN 'subjective scapular movement response' WHEN 7 THEN 'historical neck stiffness self-report' WHEN 8 THEN 'historical eye fatigue self-report'
      WHEN 9 THEN 'class location change record' WHEN 10 THEN 'parent communication boundary case' WHEN 11 THEN 'device missing-data case'
      WHEN 12 THEN 'reason for skipping personal reminder' WHEN 13 THEN 'sleep context on teaching days' ELSE 'next-month microbreak memo' END
    || '·'
    || CASE CAST((CAST(substr(page_id, -3) AS INTEGER)) / 15 AS INTEGER)
      WHEN 0 THEN 'complete record' WHEN 1 THEN 'partially missing' WHEN 2 THEN 'user self-report' WHEN 3 THEN 'device source' WHEN 4 THEN 'calendar source'
      WHEN 5 THEN 'email source' WHEN 6 THEN 'closed' WHEN 7 THEN 'pending review' WHEN 8 THEN 'not diagnostic' WHEN 9 THEN 'no external sending'
      WHEN 10 THEN 'no purchase' WHEN 11 THEN 'lowcandatamovement' WHEN 12 THEN 'classroomdatadata' WHEN 13 THEN 'historical comparison' ELSE 'reusable template' END,
    properties_json = json_object('kind','historical_teaching_recovery_reference','status',
      CASE WHEN CAST(substr(page_id, -3) AS INTEGER) % 7 = 0 THEN 'partial_missing' ELSE 'archived' END)
WHERE page_id LIKE 'notion_gt_reference_%';
UPDATE blocks
SET content_json = json_object('text', CASE parent_page_id
  WHEN 'notion_gt_microbreak_hub' THEN 'Record 28-day goals, personal authorization boundaries, service sync, and next steps; append later facts only after current MCP queries.'
  WHEN 'notion_gt_risk_log' THEN 'Record neck stiffness, eye fatigue, pain red lines, load reduction reasons, and professional evaluation suggestions; do not diagnose.'
  WHEN 'notion_gt_notification_monitor' THEN 'Record personal reminder subscriptions, triggers, read status, rescheduling, and data sources; do not use score or stage-prompt fields.'
  WHEN 'notion_gt_final_review' THEN 'consolidate actual execution, missing data, schedule changes, communication boundaries, and next-month template; do not prewrite future conclusions.'
  ELSE json_extract(content_json,'$.text') END)
WHERE block_id LIKE 'block_notion_gt_%_intro';

-- Keep each reference page's final topic, origin and archival state in its
-- structured properties instead of repeating a generic metadata object.
UPDATE pages
SET properties_json = json_object(
      'kind','historical_teaching_recovery_reference',
      'topic',title,
      'source_class',CASE (CAST(substr(page_id, -3) AS INTEGER) % 5)
        WHEN 0 THEN 'lesson_calendar' WHEN 1 THEN 'self_report'
        WHEN 2 THEN 'device_summary' WHEN 3 THEN 'private_reminder'
        ELSE 'email_archive' END,
      'record_state',CASE WHEN CAST(substr(page_id, -3) AS INTEGER) % 7 = 0
        THEN 'partial_missing' ELSE 'archived' END,
      'recorded_at',last_edited_time)
WHERE page_id LIKE 'notion_gt_reference_%';

-- Core pages are empty workspace scaffolding that predates the kickoff.
-- Future-dated creation/edit timestamps would expose post-kickoff facts.
UPDATE pages
SET created_time = '2026-06-30T23:00:00+08:00',
    last_edited_time = '2026-06-30T23:00:00+08:00'
WHERE created_time > '2026-07-01T08:10:00+08:00';
UPDATE blocks
SET created_time = '2026-06-30T23:00:00+08:00',
    last_edited_time = '2026-06-30T23:00:00+08:00'
WHERE created_time > '2026-07-01T08:10:00+08:00';
